from itertools import combinations

def min_ratio_difference(subset):
    """
    Calculates the minimum value of |e/h - g/f| for a given set of 4 numbers.
    The numbers in the subset are assumed to be positive.
    """
    if len(subset) != 4:
        return float('inf')

    # Sort the subset for consistent application of pairing rules
    A, B, C, D = sorted(subset)

    # There are 3 ways to partition {A, B, C, D} into two pairs (p1, p2)
    # We want to minimize |p1/p2 - q1/q2| where {p1, p2, q1, q2} = {A, B, C, D}

    # Pairing 1: (A, B) vs (C, D) -> |A/B - C/D|
    val1 = abs(A/B - C/D)

    # Pairing 2: (A, C) vs (B, D) -> |A/C - B/D|
    val2 = abs(A/C - B/D)

    # Pairing 3: (A, D) vs (B, C) -> |A/D - B/C|
    val3 = abs(A/D - B/C)

    return min(val1, val2, val3)

# The set of 5 numbers
S = {1, 2, 3, 4, 5}
subsets_of_4 = list(combinations(S, 4))

results = {}
overall_min = float('inf')

for i, subset in enumerate(subsets_of_4):
    min_diff = min_ratio_difference(list(subset))
    results[tuple(sorted(subset))] = min_diff
    if min_diff < overall_min:
        overall_min = min_diff

print("Results for all 5 subsets:")
for subset, diff in results.items():
    print(f"Subset {subset}: Minimum difference = {diff}")

print(f"\nOverall Minimum Ratio Difference: {overall_min}")

